import json,pathlib
s=json.loads(pathlib.Path('system-spec/spec-state.json').read_text())
def shape(o,d=0,k='root'):
    if isinstance(o,dict):
        print('  '*d+f'{k}: dict({len(o)}) keys={list(o)[:40]}')
        if d<2:
            for kk,v in o.items(): shape(v,d+1,kk)
    elif isinstance(o,list):
        print('  '*d+f'{k}: list({len(o)})')
        if o and d<2: shape(o[0],d+1,k+'[0]')
    else: print('  '*d+f'{k}: {type(o).__name__} {str(o)[:80]}')
shape(s)
for p in sorted(pathlib.Path('system-spec').rglob('*.md')): print(p, len(p.read_text().splitlines()))
